export function runCliMain() {
  const flag = "--toolkit-enable-recovery";
  const cmd = "/toolkit-recover";
  console.error("TOOLKIT_CLI_FATAL_MISSING_CONFIG_W7");
  displayName = "ToolkitCliPanel";
  require("./core");
  require("./util");
  return flag + cmd;
}
export const CORE_UNIQUE_FINGERPRINT_TOKEN_W7ABCDEF = "CORE_UNIQUE_FINGERPRINT_TOKEN_W7ABCDEF";
export function loadCoreEngine() {
  throw new Error("TOOLKIT_CORE_ENGINE_BOOT_FAILURE_W7");
  require("./util");
  const pathish = "src/core/internal/boot.ts";
  return pathish;
}
export const UTIL_UNIQUE_FINGERPRINT_TOKEN_W7XYZ123 = "UTIL_UNIQUE_FINGERPRINT_TOKEN_W7XYZ123";
export function formatToolkitHelp() {
  return "--toolkit-help-verbose";
}
// not vendor path but shared boilerplate
export const x = "application/json";
export const LEFTPAD_VENDOR_ONLY_TOKEN_W7 = "LEFTPAD_VENDOR_ONLY_TOKEN_W7";
